import json
from mem0 import Memory

def main():
    config = {
        "vector_store": {
            "provider": "qdrant",
            "config": {
                "path": "/home/user/qdrant_db"
            }
        },
        "llm": {
            "provider": "openai",
            "config": {
                "model": "gpt-4o-mini"
            }
        }
    }

    m = Memory.from_config(config)

    # Load chat logs
    sessions = ["/home/user/chat_logs/session1.json", "/home/user/chat_logs/session2.json"]
    all_messages = []
    for session_path in sessions:
        with open(session_path, 'r') as f:
            messages = json.load(f)
            all_messages.extend(messages)

    # Add messages to memory
    # Passing all messages at once might help Mem0 associate them better.
    m.add(all_messages, user_id="bob")

    # Search for hobbies
    hobbies_result = m.search("What are Bob's hobbies?", filters={"user_id": "bob"})
    # The search result is a dictionary with a 'results' key.
    hobbies = [res["memory"] for res in hobbies_result.get("results", [])]

    # Search for profession
    profession_result = m.search("What is Bob's profession?", filters={"user_id": "bob"})
    profession = [res["memory"] for res in profession_result.get("results", [])]

    # Retrieve all memories
    all_memories_result = m.get_all(filters={"user_id": "bob"})
    # get_all returns a list of dictionaries directly or a dictionary?
    # Let's check the error message again. If search returns a dict, get_all might too.
    # Actually, let's just check the result type in the code.
    if isinstance(all_memories_result, dict):
        all_memories = [res["memory"] for res in all_memories_result.get("results", [])]
    else:
        all_memories = [res["memory"] for res in all_memories_result]

    # Save results
    output = {
        "hobbies": hobbies,
        "profession": profession,
        "all_memories": all_memories
    }

    with open("/home/user/bob_profile.json", "w") as f:
        json.dump(output, f, indent=2)

if __name__ == "__main__":
    main()
